    // 30 Touching Stories of Repentance (قصص التوبة)
    val stories30 = listOf(
        TawbahStory("1", "توبة قاتل المائة نفس", "رجل من بني إسرائيل", "قتل 99 نفساً ثم كمل المائة بعابد، فسأل عالماً فقال: من يحول بينك وبين التوبة؟ اخرج إلى قرية الصالحين، فمات في الطريق واختصمت فيه الملائكة فقاست المسافة فوجدته أقرب إلى التوبة بشبر فغفر الله له.", "صحيح البخاري ومسلم"),
        TawbahStory("2", "توبة الفضيل بن عياض", "عابد الحرمين الفضيل", "كان قاطع طريق يسطو على القوافل، ارتقى جداراً لسرقة فسمع قارئاً يتلو: {أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ}، فبكى وقال: بلى يا رب قد آن! وصار إمام الزاهدين وعابد الحرمين.", "سير أعلام النبلاء"),
        TawbahStory("3", "توبة مالك بن دينار", "مالك بن دينار رحمه الله", "كان شرطياً لاهياً، ماتت ابنته فاطمة فانكسر قلبه، فرأى في المنام ثعباناً يلاحقه وابنته تنقذه وتتلو: {أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا}، فاستيقظ باكياً وتاب إلى الله حتى صار قدوة التابعين.", "كتاب التوابين لابن قدامة"),
        TawbahStory("4", "توبة كعب بن مالك", "كعب بن مالك الأنصاري", "تخلف عن غزوة تبوك دون عذر، فصدق النبي ﷺ وأمر بهجرانه 50 ليلة حتى ضاقت عليه الأرض بما رحبت، فنزلت توبته من فوق سبع سماوات في سورة التوبة.", "صحيح البخاري"),
        TawbahStory("5", "توبة ماعز بن مالك", "ماعز بن مالك رضي الله عنه", "أتى النبي ﷺ معترفاً بذنبه طالباً التطهير، فقال النبي: لقد تاب توبة لو قُسمت بين أمة لوسعتهم.", "صحيح مسلم"),
        TawbahStory("6", "توبة الغامدية", "المرأة الغامدية رضي الله عنها", "أتت معترفة وقالت: طهرني يا رسول الله، فصلى عليها النبي بعد موتها وقال لعمر: لقد تابت توبة لو تابها سبعون من أهل المدينة لقُبلت منهم.", "صحيح مسلم"),
        TawbahStory("7", "توبة أبي محجن الثقفي", "أبو محجن الثقفي", "كان مولعاً بالخمر وحبسه سعد بن أبي وقاص يوم القادسية، فطلب من زوجة سعد إطلاقه للقتال على أن يعود للقيد، فقاتل ببطولة أذهلت الجيش وأقسم ألا يعود للخمر أبداً.", "البداية والنهاية"),
        TawbahStory("8", "توبة حاطب بن أبي بلتعة", "حاطب بن أبي بلتعة البدري", "كتب كتاباً لقريش يخبرهم بمسير النبي لمكة خوفاً على قرابته، فعفا عنه النبي لشهوده بدراً وقال: لعل الله اطلع على أهل بدر فقال اعملوا ما شئتم فقد غفرت لكم.", "صحيح البخاري"),
        TawbahStory("9", "توبة شقيق البلخي", "إبراهيم بن أدهم وشقيق البلخي", "رأى في زمن القحط غلاماً مملوكاً يضحك فسأله: الناس في مجاعة وأنت تلهو؟ فقال: سيدي يملك قرية يطعمني منها، فبكى شقيق وقال: إن كان لسيدك قرية فكيف بمن سيده رب السماوات والأرض؟ فتاب من حينه.", "طبقات الأولياء"),
        TawbahStory("10", "توبة بشر الحافي", "بشر بن الحارث الحافي", "كان في لهو وطرب، فمر عابد وسأل خادمته: صاحب هذه الدار حر أم عبد؟ قالت: حر، قال: صدقتِ لو كان عبداً لاستحيا من سيده، فلما سمع بشر خرج حافياً وراءه تائباً باكياً.", "تاريخ بغداد"),
        TawbahStory("11", "توبة عكرمة بن أبي جهل", "عكرمة بن أبي جهل", "كان أشد الناس عداوة للإسلام وهرب في البحر بعد فتح مكة، فلما هاجت الأمواج قال: والله لا ينجيني إلا الإخلاص لله، فعاد تائباً وأسلم بين يدي النبي واستشهد يوم اليرموك.", "سير أعلام النبلاء"),
        TawbahStory("12", "توبة وحشي بن حرب", "قاتل حمزة رضي الله عنه", "قتل حمزة سيد الشهداء، ثم ضاقت به الأرض فأسلم وحسن إسلامه وقتل مسيلمة الكذاب في اليمامة وقال: قتلت خير الناس في جاهليتي وقتلت شر الناس في إسلامي.", "صحيح البخاري"),
        TawbahStory("13", "توبة ثمامة بن أثال", "سيد بني حنيفة", "أُسر ورُبط بسارية المسجد، فكان النبي يحسن إليه ويطلق سراحه دون فدية، فذهب واغتسل وأسلم وعاد إلى مكة ملبياً ومنع القمح عن قريش حتى يأذن النبي.", "صحيح البخاري"),
        TawbahStory("14", "توبة سحرة فرعون", "سحرة فرعون في يوم الزينة", "جمعهم فرعون لهزيمة موسى، فلما ألقى عصاه فإذا هي تلقف ما يأفكون ألقي السحرة سجداً لله وقالوا: آمنا برب العالمين، فصبروا على بطش فرعون حتى نالوا الشهادة.", "القرآن الكريم - سورة الأعراف"),
        TawbahStory("15", "توبة مؤمن آل فرعون", "رجل مؤمن من آل فرعون", "كان يكتم إيمانه ودافع عن موسى قائلاً: {أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ اللَّهُ}، ففوض أمره إلى الله فوقاه الله سيئات ما مكروا.", "سورة غافر"),
        TawbahStory("16", "توبة زاذان الكردي", "المحدث التابعي زاذان", "كان شاباً جميلاً يغني بالعود والفسوق، فمر به عبد الله بن مسعود فقال: ما أحسن هذا الصوت لو كان بالقرآن! فرمى العود وبكى ولزم ابن مسعود حتى صار من كبار المحدثين.", "تاريخ دمشق"),
        TawbahStory("17", "توبة نصوح", "الرجل الذي يضرب به المثل", "كان يدخل حمام النساء خفية، وفي يوم فُقد عقد الملكة وأغلق الباب لتفتيشهن جميعاً، فعلم أنه سيفضح فدعا الله من أعماق قلبه مخلصاً توبة صادقة ألا يعود، فوجد العقد مع غيره وتاب توبة نصوحاً.", "تفسير القرطبي"),
        TawbahStory("18", "توبة شاب بني إسرائيل المسرف", "شاب من بني إسرائيل", "عصى الله 40 سنة حتى حبس الله المطر عن قوم موسى، ونادى موسى: إن فيكم عاصياً فليخرج، فغطى الشاب رأسه وبكى وقال: يا رب عصيتك 40 سنة وأمهلتني واليوم أتوب إليك فاسترني، فنزل المطر فوراً.", "حلية الأولياء"),
        TawbahStory("19", "توبة أبي لبابة رضي الله عنه", "أبو لبابة بن عبد المنذر", "أشار إلى بني قريظة بيده نحو عنقه (أنه الذبح)، فعلم أنه خان الله ورسوله، فربط نفسه بسارية المسجد حتى نزلت توبته من الله وحلّه النبي ﷺ.", "السيرة النبوية"),
        TawbahStory("20", "توبة هلال بن أمية", "الصحابي البدري هلال", "أحد الثلاثة الذين خُلفوا عن تبوك، صدق الله ورسوله وبكى ليلاً ونهاراً حتى أنزل الله التوبة عليه مع صاحبيه.", "صحيح البخاري"),
        TawbahStory("21", "توبة مرارة بن الربيع", "الصحابي الجليل مرارة", "ثالث الثلاثة الذين خُلفوا، صبر على اعتزال الناس واستغفر ربه حتى فرج الله كربته وأنزل توبته في القرآن الكريم.", "صحيح البخاري"),
        TawbahStory("22", "توبة عبد الله بن المبارك", "إمام المحدثين والمجاهدين", "كان شاباً لاهياً يعزف على العود، فاستيقظ ليلة على صوت طائر ينشد: {أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا}، فكسر عوده وأقبل على طلب العلم والحديث والجهاد.", "سير أعلام النبلاء"),
